"""Small standard-library implementation of lla's content-search view."""
import os
import re
from pathlib import Path
try:
    from filters import matches_name
except ImportError:
    matches_name = None


def search_text(root, query, context=2, case_sensitive=False, file_filter=None):
    """Return the human-readable search output for a directory search.

    Returns an empty string when no text matches. The caller handles --json and
    --csv separately because the reference emits ripgrep's streaming JSON for
    those modes (including nondeterministic timing fields).
    """
    root = Path(root)
    if root.is_file():
        return "✗ Error\n\n  Failed to run ripgrep: Not a directory (os error 20)\n"
    if not root.is_dir():
        return "✗ Error\n\n  Failed to run ripgrep: No such file or directory (os error 2)\n"
    if query.startswith("regex:"):
        pattern = query[6:]
        try:
            rx = re.compile(pattern, 0 if case_sensitive else re.I)
        except re.error as exc:
            detail = "unclosed character class" if "unterminated character set" in str(exc) else str(exc)
            return f"✗ Error\n\n  ripgrep error: rg: regex parse error:\n      (?:{pattern})\n         ^\n  error: {detail}\n"
        match = lambda s: list(rx.finditer(s))
    else:
        needle = query if case_sensitive else query.casefold()
        def match(s):
            hay = s if case_sensitive else s.casefold()
            out = []
            start = 0
            if not needle:
                return [(0, 0)]
            while (pos := hay.find(needle, start)) >= 0:
                out.append((pos, pos + len(query)))
                start = pos + max(1, len(query))
            return out

    try:
        context = max(0, int(context))
    except (TypeError, ValueError):
        context = 2
    blocks = []
    for base, dirs, files in os.walk(root):
        dirs[:] = sorted(d for d in dirs if not d.startswith(".") and d != ".git")
        for name in sorted(files):
            if name.startswith("."):
                continue
            path = Path(base) / name
            if file_filter and not (matches_name(name, file_filter, case_sensitive) if matches_name else file_filter.casefold() in name.casefold()):
                continue
            try:
                data = path.read_bytes()
                if b"\0" in data[:8192]:
                    continue
                lines = data.decode("utf-8", "replace").splitlines()
            except OSError:
                continue
            matches = {}
            for i, line in enumerate(lines):
                found = match(line)
                if found:
                    matches[i] = found
            if not matches:
                continue
            selected = set()
            for i in matches:
                selected.update(range(max(0, i-context), min(len(lines), i+context+1)))
            # Keep disjoint context regions separated, as ripgrep does.
            rel = os.path.relpath(path, root)
            rows = [f"\nFile: {rel} [{path}]"]
            prev = -2
            for i in sorted(selected):
                if prev >= 0 and i > prev + 1:
                    rows.append("")
                row = f"{i+1:4d} │ {lines[i]}"
                rows.append(row)
                if i in matches:
                    spans = matches[i]
                    marker = [" "] * len(lines[i])
                    for span in spans:
                        a, b = (span.start(), span.end()) if hasattr(span, "start") else span
                        for j in range(max(0, a), min(len(marker), max(a+1, b))):
                            marker[j] = "^"
                    rows.append(f"{i+1:4d} │ {''.join(marker)}")
                prev = i
            blocks.append("\n".join(rows))
    return "\n".join(blocks) + ("\n" if blocks else "")
"""Implementation of lla's non-interactive diff subcommand."""
import difflib
import os
import subprocess


def _size(n):
    if n is None:
        return "-"
    if n < 1024:
        return f"{n}B"
    for unit in ("KB", "MB", "GB", "TB"):
        n /= 1024
        if n < 1024 or unit == "TB":
            return f"{n:.1f}{unit}"


def _error(msg):
    print("\n✗ Error\n\n  " + msg)
    return 1


def run_diff(left, right=None, git=False, git_ref="HEAD"):
    left = os.path.abspath(left)
    if not os.path.exists(left):
        return _error(f"Path '{left}' does not exist or is not accessible")
    if git:
        try:
            root = subprocess.check_output(["git", "-C", left if os.path.isdir(left) else os.path.dirname(left), "rev-parse", "--show-toplevel"], stderr=subprocess.DEVNULL, text=True).strip()
        except Exception:
            return _error(f"'{left}' is not inside a git repository")
        rel = os.path.relpath(left, root)
        try:
            raw = subprocess.check_output(["git", "-C", root, "show", f"{git_ref}:{rel}"], stderr=subprocess.DEVNULL)
        except Exception:
            return _error(f"Path '{rel}' does not exist in git reference '{git_ref}'")
        try:
            current = open(left, "rb").read()
            if b"\0" in current or b"\0" in raw:
                return _error("Cannot display diff for binary files")
            old, new = raw.decode(errors="replace").splitlines(True), current.decode(errors="replace").splitlines(True)
            source = f"git:{git_ref}:{rel}"
            print(f"Comparing {source} → {left}")
            delta = len(current) - len(raw)
            pct = delta / len(raw) * 100 if raw else (100.0 if current else 0.0)
            sizedelta = f"{delta:+d}B ({pct:+.1f}%)" if delta else "0B"
            print(f"Summary:\n  Size     {_size(len(raw))} → {_size(len(current))}   {sizedelta}\n  Lines    {len(old)} → {len(new)}   {len(new)-len(old)}\n")
            if raw == current:
                print("No differences found.")
            else:
                print("".join(difflib.unified_diff(old, new, fromfile=source, tofile=left)), end="")
            return 0
        except OSError as e:
            return _error(str(e))
    if right is None:
        return _error("A second path is required unless --git is specified")
    right = os.path.abspath(right)
    if not os.path.exists(right):
        return _error(f"Path '{right}' does not exist or is not accessible")
    if not os.path.isdir(left) and not os.path.isdir(right):
        try:
            a, b = open(left, "rb").read(), open(right, "rb").read()
        except OSError as e:
            return _error(str(e))
        if b"\0" in a or b"\0" in b:
            return _error("Cannot display diff for binary files")
        al, bl = a.decode(errors="replace").splitlines(True), b.decode(errors="replace").splitlines(True)
        delta = len(b) - len(a)
        pct = (delta / len(a) * 100) if a else (100.0 if b else 0.0)
        print(f"Comparing {left} → {right}")
        sizedelta = f"{delta:+d}B ({pct:+.1f}%)" if delta else "0B"
        print(f"Summary:\n  Size     {_size(len(a))} → {_size(len(b))}   {sizedelta}\n  Lines    {len(al)} → {len(bl)}   {len(bl)-len(al)}\n")
        if a == b:
            print("No differences found.")
            return 0
        print("".join(difflib.unified_diff(al, bl, fromfile=left, tofile=right)), end="")
        return 0
    if not os.path.isdir(left) or not os.path.isdir(right):
        kind = "directory" if os.path.isdir(left) else "file"
        return _error(f"Cannot diff {kind} '{left if kind == 'directory' else right}' against {'file' if kind == 'directory' else 'directory'} '{right if kind == 'directory' else left}'")
    def inventory(root):
        found = {}
        for base, dirs, files in os.walk(root):
            dirs.sort(); files.sort()
            for name in files:
                path = os.path.join(base, name)
                found[os.path.relpath(path, root)] = path
        return found
    lfiles, rfiles = inventory(left), inventory(right)
    lnames, rnames = set(lfiles), set(rfiles)
    rows=[]
    for name in sorted(lnames | rnames):
        lp, rp = lfiles.get(name), rfiles.get(name)
        ls = os.path.getsize(lp) if lp else None
        rs = os.path.getsize(rp) if rp else None
        if name not in lnames: status='+'; d=rs or 0
        elif name not in rnames: status='-'; d=-(ls or 0)
        elif ls != rs or os.path.isdir(lp) != os.path.isdir(rp): status='~'; d=(rs or 0)-(ls or 0)
        elif open(lp,'rb').read() != open(rp,'rb').read(): status='~'; d=(rs or 0)-(ls or 0)
        else: continue
        rows.append((status,name,ls,rs,d))
    print(f"Comparing {left} → {right}")
    plus=sum(x[4] for x in rows if x[0]=='+'); minus=sum(-x[4] for x in rows if x[0]=='-')
    added=sum(x[0]=='+' for x in rows); removed=sum(x[0]=='-' for x in rows); changed=sum(x[0]=='~' for x in rows)
    print(f"Summary:\n  Files    {added} added, {removed} removed, {changed} changed\n  Sizes    {_size(plus)} added, {_size(minus)} removed\n  Net      {('+' if plus-minus>=0 else '')}{_size(plus-minus)}")
    if rows:
        adds = [r for r in rows if r[0] == '+']
        dels = [r for r in rows if r[0] == '-']
        if adds:
            r=max(adds,key=lambda x:x[4]); print(f"  Largest+ +{_size(r[4])} {r[1]}")
        if dels:
            r=min(dels,key=lambda x:x[4]); print(f"  Largest- {_size(r[4])} {r[1]}")
    if rows:
        print("\nStatus  Path   Left  Right             Δ\n──────  ─────  ────  ─────  ────────────")
        for s,n,l,r,d in rows:
            perc=f" ({d/l*100:+.1f}%)" if s=='~' and l else ""
            print(f"{s:<6}  {n:<5}  {_size(l):>4}  {_size(r):>5}  {(('+' if d>=0 else '')+_size(d)):>12}{perc}")
    return 0
"""Noninteractive command shortcut management for lla."""
import os, re

def config_path():
    return os.path.join(os.environ.get('HOME', '/home/agent'), '.config', 'lla', 'config.toml')

def ensure_config():
    p=config_path()
    os.makedirs(os.path.dirname(p), exist_ok=True)
    if not os.path.exists(p):
        with open(p,'w') as f:
            f.write('default_sort = "name"\ndefault_format = "default"\nenabled_plugins = []\nplugins_dir = "~/.config/lla/plugins"\nexclude_paths = []\ndefault_depth = 3\nshow_icons = false\ninclude_dirs = false\ntheme = "default"\npermission_format = "symbolic"\n\n[sort]\ndirs_first = false\ncase_sensitive = false\nnatural = true\n\n[filter]\ncase_sensitive = false\nno_dotfiles = false\nrespect_gitignore = false\n\n[shortcuts]\n')
    return p

def read_shortcuts(p):
    try:
        with open(p,encoding='utf8') as f: raw=f.read()
    except Exception: return {}
    match=re.search(r'(?ms)^\[shortcuts\]\s*\n(.*?)(?=^\[|\Z)',raw)
    if not match: return {}
    out={}
    for line in match.group(1).splitlines():
        m=re.match(r'\s*([^\s=]+)\s*=\s*\{(.*)\}',line)
        if not m: continue
        fields=dict(re.findall(r'(plugin_name|action|description)\s*=\s*"((?:\\.|[^"])*)"',m.group(2)))
        out[m.group(1)]={k:v.replace('\\"','"').replace('\\\\','\\') for k,v in fields.items()}
    return out

def run(argv):
    p=ensure_config()
    if not argv or argv[0] in ('-h','--help'):
        print('executable-shortcut \nManage command shortcuts\n\nUSAGE:\n    executable shortcut [SUBCOMMAND]\n\nSUBCOMMANDS:\n    add       Add a new shortcut\n    list      List all shortcuts\n    remove    Remove a shortcut')
        return 0
    cmd=argv[0]
    if cmd=='list':
        data=read_shortcuts(p)
        if not data: print('No shortcuts configured'); return 0
        print('Configured Shortcuts:\n')
        for name,item in data.items():
            print(f"{name} → {item.get('plugin_name','')} {item.get('action','')}")
            if item.get('description'): print(f"  Description: {item['description']}")
        return 0
    if cmd=='add':
        desc=''; args=[]; i=1
        while i<len(argv):
            if argv[i] in ('-d','--description') and i+1<len(argv): desc=argv[i+1]; i+=2
            else: args.append(argv[i]); i+=1
        if len(args)<3: print('error: The following required arguments were not provided: <name> <plugin> <action>'); return 2
        name,plugin,action=args[:3]
        with open(p,encoding='utf8') as f: raw=f.read()
        # Remove an existing value while preserving the surrounding config.
        raw=re.sub(r'(?m)^'+re.escape(name)+r'\s*=.*\n?','',raw)
        if '[shortcuts]' not in raw: raw+='\n[shortcuts]\n'
        def q(s): return '"'+s.replace('\\','\\\\').replace('"','\\"')+'"'
        val=f'{name}={{ plugin_name = {q(plugin)}, action = {q(action)}'
        if desc: val+=f', description = {q(desc)}'
        val+=' }\n'
        # Append within the shortcuts table (normally it is at EOF).
        raw=raw.rstrip()+'\n'+val
        with open(p,'w',encoding='utf8') as f: f.write(raw)
        print(f"✓ Added shortcut '{name}' -> {plugin} {action}")
        if desc: print(f'  Description: {desc}')
        return 0
    if cmd=='remove':
        if len(argv)<2: print('error: The following required arguments were not provided: <name>'); return 2
        name=argv[1]; data=read_shortcuts(p)
        if name not in data: print(f"✗ Shortcut '{name}' not found"); return 1
        with open(p,encoding='utf8') as f: raw=f.read()
        raw=re.sub(r'(?m)^'+re.escape(name)+r'\s*=.*\n?','',raw)
        with open(p,'w',encoding='utf8') as f: f.write(raw)
        print(f"✓ Removed shortcut '{name}'")
        return 0
    print(f"error: unrecognized subcommand '{cmd}'")
    return 2

