"""Small standard-library implementation of lla's content-search view."""
import os
import re
from pathlib import Path
try:
    from filters import matches_name
except ImportError:
    matches_name = None


def search_text(root, query, context=2, case_sensitive=False, file_filter=None):
    """Return the human-readable search output for a directory search.

    Returns an empty string when no text matches. The caller handles --json and
    --csv separately because the reference emits ripgrep's streaming JSON for
    those modes (including nondeterministic timing fields).
    """
    root = Path(root)
    if root.is_file():
        return "✗ Error\n\n  Failed to run ripgrep: Not a directory (os error 20)\n"
    if not root.is_dir():
        return "✗ Error\n\n  Failed to run ripgrep: No such file or directory (os error 2)\n"
    if query.startswith("regex:"):
        pattern = query[6:]
        try:
            rx = re.compile(pattern, 0 if case_sensitive else re.I)
        except re.error as exc:
            detail = "unclosed character class" if "unterminated character set" in str(exc) else str(exc)
            return f"✗ Error\n\n  ripgrep error: rg: regex parse error:\n      (?:{pattern})\n         ^\n  error: {detail}\n"
        match = lambda s: list(rx.finditer(s))
    else:
        needle = query if case_sensitive else query.casefold()
