"""Tree view renderer for collected listing entries."""
import os


def render_tree(root, entries, max_depth=3, icons=False):
    root = os.fspath(root)
    label = os.path.basename(os.path.abspath(root)) or root
    if os.path.isfile(root):
        return f"└── {label}\n\n"
    if icons: label=' '+label
    if label != os.path.sep:
        label += "/"
    rows = [f"└── {label}"]
    by_rel = {}
    for e in entries:
        path = e.get('path', '')
        try:
            rel = os.path.relpath(path, root)
        except ValueError:
            continue
        if rel == '.' or rel.startswith('..'):
            continue
        depth = rel.count(os.sep) + 1
        if depth <= max_depth:
            by_rel[rel] = e
    children = {}
    for rel in by_rel:
        parent = os.path.dirname(rel)
        children.setdefault(parent, []).append(rel)
    def walk(parent, prefix, level):
        kids = sorted(children.get(parent, []), key=lambda rel: os.path.basename(rel).casefold())
        for idx, rel in enumerate(kids):
            last = idx == len(kids)-1
            e = by_rel[rel]
            name = e.get('name') or os.path.basename(rel)
            if not name.startswith((' ',' ',' ',' ',' ',' ',' ',' ',' ',' ')) and icons:
                ext=os.path.splitext(name)[1][1:].lower()
                icon='' if e.get('file_type')=='dir' else '' if e.get('file_type')=='symlink' else {'rs':'','toml':'','py':'','js':'','ts':'','sh':'','png':'','jpg':'','jpeg':'','gif':'','md':'','txt':''}.get(ext,'')
                name=icon+' '+name
            if e.get('file_type') == 'dir' and not name.endswith('/'):
                name += '/'
            rows.append(prefix + ('└── ' if last else '├── ') + name)
            if e.get('file_type') == 'dir' and level < max_depth:
                walk(rel, prefix + ('    ' if last else '│   '), level+1)
    walk('', '    ', 1)
    return '\n'.join(rows) + '\n\n'

